{"command":"cd /workspace && cat > compose.py << 'PY'
import json

# Channel map
CH = {'kick':0,'snare':1,'hihat':2,'bass':3,'lead':4,'arp':5,'pad':6,'fx':7}

# Helper: note string -> semitone count from C-0
NOTE_NAMES = ['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def note(n):
    # n like 'C-4', 'A#2'
    name = n[:2]
    oct = int(n[2])
    return NOTE_NAMES.index(name) + oct*12

def add(events, pat, row, ch, note=None, ins=None, vol=None, eff=None, effp=None):
    events.setdefault(pat, []).append((row, ch, note, ins, vol, eff, effp))

# Pattern 0: Intro 4 bars (64 rows) Am-F-C-G
# Drums: kick beats, snare backbeat; hihat enters bar 4
for row in range(0,64,4):
    # hihat every 4 rows except first 3 bars
    if row >= 36:
        add('events', 0, row, CH['hihat'], 'F-4', 3, 40)
# kick on beats
for row in [0,16,32,48]:
    add('events', 0, row, CH['kick'], 'C-2', 1)
# snare backbeat
for row in [8,24,40,56]:
    add('events', 0, row, CH['snare'], 'C-2', 2)
# Bass: A2,F2,C2,G2 each bar
bass_prog0 = [('A-2',0),('F-2',16),('C-3',32),('G-2',48)]
for n,r in bass_prog0:
    add('events', 0, r, CH['bass'], n, 4, 48)
    # volume slide down
    add('events', 0, r, CH['bass'], None, None, None, 0xA, 0x0F)  # A0F fade down? actually A0F = vol slide down by F
# Pad chords (top notes) each bar
pad0 = [('A-3',0),('F-3',16),('E-3',32),('G-3',48)]
for n,r in pad0:
    add('events', 0, r, CH['pad'], n, 7, 32)

# Pattern 1: Build 4 bars; full drums; arp enters; lead short motif bar 3-4
for row in range(0,64,4):
    add('events', 1, row, CH['hihat'], 'F-4', 3, 36)
for row in [0,16,32,48]:
    add('events', 1, row, CH['kick'], 'C-2', 1)
for row in [8,24,40,56]:
    add('events', 1, row, CH['snare'], 'C-2', 2)
for n,r in bass_prog0:
    add('events', 1, r, CH['bass'], n, 4, 48)
    add('events', 1, r, CH['bass'], None, None, None, 0xA, 0x0B)
# Arp: 16th triplets per chord
for bar,(root,base_r) in enumerate([('A-4',0),('F-4',16),('C-5',32),('G-4',48)]):
    for i in range(4):
        r = base_r + i*4
        # use arpeggio effect 0 3 7
        add('events', 1, r, CH['arp'], root, 6, 44, 0, 0x37)
# Lead motif bars 3-4 (rows 32-63): A4 C5 E5 D5 C5 A4 G4 A4 | G4 C5 E5 D5 C5 G4 F4 E4
lead_motif1 = [('A-4',32),('C-5',36),('E-5',40),('D-5',44),('C-5',48),('A-4',52),('G-4',56),('A-4',60),
               ('G-4',64)]
# Actually pattern 1 is 64 rows, so only up to 60. Use first 8 notes only for bar 3-4 split? Let's put first 8 notes in bar 3 and 4.
# Bar 3 (32-47): A4 C5 E5 D5 C5 A4 G4 A4
# Bar 4 (48-63): G4 C5 E5 D5 C5 G4 F4 E4
lead1 = [('A-4',32),('C-5',34),('E-5',36),('D-5',38),('C-5',40),('A-4',42),('G-4',44),('A-4',46),
         ('G-4',48),('C-5',50),('E-5',52),('D-5',54),('C-5',56),('G-4',58),('F-4',60),('E-4',62)]
for n,r in lead1:
    add('events', 1, r, CH['lead'], n, 5, 48)

# Pattern 2: Main A full. Chords Am-F-C-G.
# Drums
for row in range(0,64,4):
    if row%8==0:
        add('events', 2, row, CH['hihat'], 'F-4', 3, 40)
    else:
        add('events', 2, row, CH['hihat'], 'F-4', 3, 28)
for row in [0,16,32,48]:
    add('events', 2, row, CH['kick'], 'C-2', 1)
for row in [8,24,40,56]:
    add('events', 2, row, CH['snare'], 'C-2', 2)
# Bass
for n,r in bass_prog0:
    add('events', 2, r, CH['bass'], n, 4, 52)
    add('events', 2, r, CH['bass'], None, None, None, 0xA, 0x0B)
# Arp
for bar,(root,base_r) in enumerate([('A-4',0),('F-4',16),('C-5',32),('G-4',48)]):
    for i in range(4):
        r = base_r + i*4
        add('events', 2, r, CH['arp'], root, 6, 40, 0, 0x37)
# Lead melody (2 bars)
lead2 = [('A-4',0),('C-5',2),('E-5',4),('D-5',6),('C-5',8),('A-4',10),('G-4',12),('A-4',14),
         ('G-4',16),('C-5',18),('E-5',20),('D-5',22),('C-5',24),('G-4',26),('F-4',28),('E-4',30),
         ('F-4',32),('A-4',34),('C-5',36),('D-5',38),('C-5',40),('A-4',42),('F-4',44),('E-4',46),
         ('E-4',48),('G-4',50),('B-4',52),('A-4',54),('G-4',56),('E-4',58),('D-4',60),('C-4',62)]
for n,r in lead2:
    add('events', 2, r, CH['lead'], n, 5, 52)
# add vibrato to first note and sustained notes? We'll skip for simplicity; maybe on long notes
# Pad
for n,r in pad0:
    add('events', 2, r, CH['pad'], n, 7, 32)

# Pattern 3: Main A variation - lead octave up + hihat shuffle
for row in range(0,64,4):
    add('events', 3, row, CH['hihat'], 'F-4', 3, 32 if row%8==4 else 24)
for row in [0,16,32,48]:
    add('events', 3, row, CH['kick'], 'C-2', 1)
for row in [8,24,40,56]:
    add('events', 3, row, CH['snare'], 'C-2', 2)
for n,r in bass_prog0:
    add('events', 3, r, CH['bass'], n, 4, 52)
    add('events', 3, r, CH['bass'], None, None, None, 0xA, 0x0A)
for bar,(root,base_r) in enumerate([('A-4',0),('F-4',16),('C-5',32),('G-4',48)]):
    for i in range(4):
        r = base_r + i*4
        add('events', 3, r, CH['arp'], root, 6, 36, 0, 0x37)
# Lead octave up variation
lead3 = [('A-5',0),('C-6',2),('E-6',4),('D-6',6),('C-6',8),('A-5',10),('G-5',12),('A-5',14),
         ('G-5',16),('C-6',18),('E-6',20),('D-6',22),('C-6',24),('G-5',26),('F-5',28),('E-5',30),
         ('F-5',32),('A-5',34),('C-6',36),('D-6',38),('C-6',40),('A-5',42),('F-5',44),('E-5',46),
         ('E-5',48),('G-5',50),('B-5',52),('A-5',54),('G-5',56),('E-5',58),('D-5',60),('C-5',62)]
for n,r in lead3:
    add('events', 3, r, CH['lead'], n, 5, 48)
for n,r in pad0:
    add('events', 3, r, CH['pad'], n, 7, 28)

# Pattern 4: Main B Dm-Am-F-C
bass_prog4 = [('D-3',0),('A-2',16),('F-2',32),('C-3',48)]
pad4 = [('D-4',0),('A-3',16),('F-3',32),('E-4',48)]  # C chord top E
for row in range(0,64,4):
    add('events', 4, row, CH['hihat'], 'F-4', 3, 36)
for row in [0,16,32,48]:
    add('events', 4, row, CH['kick'], 'C-2', 1)
for row in [8,24,40,56]:
    add('events', 4, row, CH['snare'], 'C-2', 2)
for n,r in bass_prog4:
    add('events', 4, r, CH['bass'], n, 4, 52)
    add('events', 4, r, CH['bass'], None, None, None, 0xA, 0x0B)
# Arp roots D,A,F,C
for bar,(root,base_r) in enumerate([('D-4',0),('A-3',16),('F-4',32),('C-5',48)]):
    for i in range(4):
        r = base_r + i*4
        add('events', 4, r, CH['arp'], root, 6, 40, 0, 0x37)
# Lead melody for B
lead4 = [('D-5',0),('F-5',2),('A-5',4),('G-5',6),('F-5',8),('D-5',10),('C-5',12),('D-5',14),
         ('C-5',16),('E-5',18),('A-5',20),('G-5',22),('E-5',24),('C-5',26),('B-4',28),('A-4',30),
         ('A-4',32),('C-5',34),('F-5',36),('G-5',38),('F-5',40),('C-5',42),('A-4',44),('G-4',46),
         ('G-4',48),('C-5',50),('E-5',52),('D-5',54),('C-5',56),('G-4',58),('F-4',60),('E-4',62)]
for n,r in lead4:
    add('events', 4, r, CH['lead'], n, 5, 52)
for n,r in pad4:
    add('events', 4, r, CH['pad'], n, 7, 32)

# Pattern 5: Breakdown 4 bars Em-G-D-A
# Drums minimal: kick on 1, snare sparse, build roll at end
for row in [0,16,32,48]:
    add('events', 5, row, CH['kick'], 'C-2', 1)
for row in [8,40]:
    add('events', 5, row, CH['snare'], 'C-2', 2)
for row in range(56,64):
    add('events', 5, row, CH['snare'], 'C-2', 2)  # roll
# hihat half time
for row in [4,12,20,28,36,44,52,60]:
    add('events', 5, row, CH['hihat'], 'F-4', 3, 24)
bass_prog5 = [('E-2',0),('G-2',16),('D-3',32),('A-2',48)]
for n,r in bass_prog5:
    add('events', 5, r, CH['bass'], n, 4, 44)
pad5 = [('B-3',0),('D-4',16),('A-4',32),('C-5',48)]
for n,r in pad5:
    add('events', 5, r, CH['pad'], n, 7, 28)
# Arp sparse
for bar,(root,base_r) in enumerate([('E-4',0),('G-4',16),('D-4',32),('A-4',48)]):
    for i in [0,2]:
        r = base_r + i*4
        add('events', 5, r, CH['arp'], root, 6, 32, 0, 0x37)
# Lead: slow rising line
lead5 = [('E-4',0),('G-4',8),('B-4',16),('D-5',24),('E-5',32),('G-5',40),('B-5',48),('E-6',56)]
for n,r in lead5:
    add('events', 5, r, CH['lead'], n, 5, 40)
    # vibrato
    add('events', 5, r+2, CH['lead'], None, None, None, 0x4, 0x8A)

# Pattern 6: Main A return - fuller, maybe with crash at start
